    static void recovery(){for(String id:IDS.subList(0,2))for(UUID p:List.of(A,B))for(boolean extra:List.of(false,true)){
        var m=game(id,p);var older=hand(m,p,"supporter");m.discardHandCardsByEffect(p,p,List.of(older.instanceId()));var cost=hand(m,p,"supporter");var otherCynthia=hand(m,p,"trainer");m.discardHandCardsByEffect(p,p,List.of(otherCynthia.instanceId()));var source=hand(m,p,"trainer");int size=m.privateView(p).hand().size();int deck=m.privateView(p).deck().size();play(m,p);mode(m,p,extra?1:0);if(extra){check(m.effectCardPrompt(p).candidates().contains(cost)&&m.privateView(p).discard().contains(older),"Recovery occurred before cost selection");submit(m,p,List.of(cost));}var q=m.effectCardPrompt(p);check(q.minimum()==1&&q.candidates().equals(List.of(older)),"Cynthia offered same name or just-paid physical Supporter");if(extra){var before=m.clientView(p);GeneratedRuleBatch8Test.reject(()->submit(m,p,List.of(cost)));check(m.clientView(p).equals(before),"Rejected cost recovery changed state");}GeneratedRuleBatch8Test.reject(()->submit(m,p,List.of(otherCynthia)));GeneratedRuleBatch8Test.reject(()->submit(m,p,List.of()));submit(m,p,List.of(older));NonPokemonBatch67Test.settle(m);check(m.privateView(p).hand().contains(older)&&m.privateView(p).discard().containsAll(extra?List.of(cost,source,otherCynthia):List.of(source,otherCynthia))&&m.privateView(p).hand().size()==size+(extra?2:0)&&m.privateView(p).deck().size()==deck-(extra?3:0),"Cynthia recovery/draw/cost wrong");
    }}
    static void recoveryGates(){for(UUID p:List.of(A,B))for(int deck:List.of(0,1,2,3,4))for(boolean existing:List.of(false,true))for(int extraCards:List.of(0,1)){
        var m=game(IDS.getFirst(),p);stock(m,p,Collections.nCopies(deck,"basic"));if(existing)m.discardHandCardsByEffect(p,p,List.of(hand(m,p,"supporter").instanceId()));var source=hand(m,p,"trainer");var cost=hand(m,p,"supporter");var keep=extraCards==1?List.of(source,cost):List.of(source);var removed=m.privateView(p).hand().stream().filter(c->!keep.contains(c)).toList();var handZone=PairedTrainerPlayTest.zone(m,p,"hand");var lost=PairedTrainerPlayTest.zone(m,p,"lostZone");handZone.removeAll(removed);lost.addAll(removed);
        boolean playable=existing||deck>0&&extraCards==1;var before=m.privateView(p);check(m.canPlayTrainer(p,source.instanceId(),null)==playable,"Cynthia empty-deck/discard/hand preflight");if(!playable){GeneratedRuleBatch8Test.reject(()->play(m,p));check(m.privateView(p).equals(before),"Unusable Cynthia moved card");continue;}play(m,p);check(m.canChooseEffectOption(p,1)==(deck>0&&extraCards==1),"Cynthia extra gate ignored projected hand or empty deck");if(deck>0&&extraCards==1){mode(m,p,1);submit(m,p,List.of(cost));NonPokemonBatch67Test.settle(m);check(m.privateView(p).discard().contains(cost)&&m.privateView(p).hand().size()==(existing?1:0)+Math.min(3,deck),"Cynthia recovered its payment or failed short draw without initial Supporter");}else{mode(m,p,0);NonPokemonBatch67Test.settle(m);check(m.privateView(p).hand().size()==extraCards+1,"Base recovery required extra payment");}
    }}
    static void search(){for(String id:IDS.subList(2,4))for(UUID p:List.of(A,B))for(boolean extra:List.of(false,true))for(int mask=0;mask<8;mask++){
        if(!extra&&mask>1)continue;var m=game(id,p);var cards=stock(m,p,List.of("stadium","tool","special","energy","basic","item","supporter"));var source=hand(m,p,"trainer");var cost=m.privateView(p).hand().stream().filter(c->!c.equals(source)).limit(2).toList();int size=m.privateView(p).hand().size();var rng=m.randomTranscript();play(m,p);check(m.effectCardReveal()==null&&m.privateView(p).deck().containsAll(cards),"Search leaked before mode choice");mode(m,p,extra?1:0);if(extra){check(m.effectCardPrompt(p).candidates().stream().noneMatch(cards::contains),"Deck candidates could pay hand cost");submit(m,p,cost);}var q=m.effectCardPrompt(p);check(q.minimum()==0&&q.maximum()==(extra?3:1)&&new HashSet<>(q.candidates()).equals(new HashSet<>(extra?cards.subList(0,3):cards.subList(0,1)))&&m.clientView(other(p)).effectSelection()==null,"Guzma filter or private deck privacy");var chosen=new ArrayList<CardInstance>();for(int i=0;i<(extra?3:1);i++)if((mask&(1<<i))!=0)chosen.add(cards.get(i));int random=m.randomTranscript().size();submit(m,p,chosen);if(!chosen.isEmpty()){var reveal=m.effectCardReveal();check(reveal!=null&&new HashSet<>(reveal.cardIds()).equals(new HashSet<>(chosen.stream().map(CardInstance::definitionId).toList())),"Guzma should reveal chosen types together");m.acknowledgeEffectReveal(other(p),reveal.id());}NonPokemonBatch67Test.settle(m);check(m.privateView(p).hand().containsAll(chosen)&&m.privateView(p).hand().size()==size-1-(extra?2:0)+chosen.size()&&m.privateView(p).discard().contains(source)&&m.randomTranscript().size()-random==cards.size()-chosen.size()-1,"Guzma transfer, exact cost or single shuffle");check(random==rng.size(),"Guzma shuffled before all three selections");
    }}
    static void kindDuplicates(){for(UUID p:List.of(A,B))for(String kind:List.of("stadium","tool","special")){var m=game(IDS.get(2),p);var cards=stock(m,p,List.of(kind,kind,"basic"));play(m,p);mode(m,p,1);submit(m,p,m.effectCardPrompt(p).candidates().subList(0,2));var q=m.effectCardPrompt(p);var before=m.clientView(p);var rng=m.randomTranscript();GeneratedRuleBatch8Test.reject(()->submit(m,p,cards.subList(0,2)));GeneratedRuleBatch8Test.reject(()->submit(m,p,List.of(cards.getLast())));check(before.equals(m.clientView(p))&&rng.equals(m.randomTranscript())&&m.effectCardReveal()==null,"Invalid repeated category revealed/moved/shuffled");m.toggleEffectCard(p,q.resolutionId(),q.step(),cards.getFirst().instanceId());check(!m.canSelectEffectCard(p,cards.get(1).instanceId())&&m.effectCardPrompt(p).candidates().stream().noneMatch(c->c.equals(cards.get(1))),"UI/AI offered second card of selected category");m.toggleEffectCard(p,q.resolutionId(),q.step(),cards.getFirst().instanceId());check(m.canSelectEffectCard(p,cards.get(1).instanceId()),"Deselect did not restore kind");submit(m,p,List.of(cards.get(1)));NonPokemonBatch67Test.settle(m);}}
